def directed_note_controls() -> str: return '''<form id='gwa-note-form' class='gwa-note-form' novalidate><style>#directed-note-controls{color:#173a35;font:inherit;max-width:375px;width:100%;overflow-x:hidden}#directed-note-controls *{box-sizing:border-box}#directed-note-controls .gwa-note-form{background:#fffef9;border:1px solid #dce3d5;border-radius:10px;padding:12px;display:grid;gap:12px;width:100%;max-width:375px;min-width:0;overflow:hidden;font:inherit}#directed-note-controls .gwa-note-field{display:grid;gap:6px;min-width:0}#directed-note-controls label{font-weight:600;font-size:14px}#directed-note-controls select,#directed-note-controls input,#directed-note-controls textarea{width:100%;min-width:0;min-height:44px;border:1px solid #dce3d5;border-radius:8px;background:#fffef9;color:#173a35;font:inherit;padding:10px}#directed-note-controls textarea{min-height:96px;resize:vertical}#directed-note-controls button{min-height:44px;width:100%;border:0;border-radius:8px;background:#215b48;color:#fffef9;font:inherit;font-weight:700;padding:10px 14px;cursor:pointer}#directed-note-controls button:disabled{opacity:.55;cursor:not-allowed}#directed-note-controls .gwa-note-help,#directed-note-controls .gwa-note-empty{margin:0;font-size:13px;line-height:1.35;overflow-wrap:anywhere}#directed-note-controls .gwa-note-alert{margin:0;padding:10px;border:1px solid #b42318;border-radius:8px;background:#fff1f0;color:#7a271a;font-size:13px;overflow-wrap:anywhere}#directed-note-controls .gwa-note-status{margin:0;padding:10px;border:1px solid #215b48;border-radius:8px;background:#f1f7f3;color:#173a35;font-size:13px;overflow-wrap:anywhere}</style><p class='gwa-note-help'>Añade contexto manual a un envío existente. No se envía ningún correo ni se crea un CRM o recordatorio.</p><p id='gwa-note-empty' class='gwa-note-empty' hidden>No hay un envío de email existente en este hilo. Registra uno para añadir una nota o respuesta.</p><div class='gwa-note-field'><label for='gwa-note-record'>Envío relacionado</label><select id='gwa-note-record' name='record' required></select></div><div class='gwa-note-field'><label for='gwa-note-kind'>Tipo de interacción</label><select id='gwa-note-kind' name='kind' required><option value='note'>Nota</option><option value='response'>Respuesta</option></select></div><div class='gwa-note-field'><label for='gwa-note-body'>Respuesta o nota</label><textarea id='gwa-note-body' name='body' required rows='4'></textarea></div><div class='gwa-note-field'><label for='gwa-note-date'>Fecha de interacción</label><input id='gwa-note-date' name='date' type='datetime-local' required></div><button id='gwa-note-submit' type='submit'>Guardar interacción</button><p id='gwa-note-alert' class='gwa-note-alert' role='alert' hidden></p><p id='gwa-note-status' class='gwa-note-status' role='status' hidden></p><script>(function(){'use strict';var host=document.getElementById('directed-note-controls');if(!host)return;var form=document.getElementById('gwa-note-form');if(!form)return;if(form.parentNode!==host)host.appendChild(form);if(form.getAttribute('data-gwa-note-bound')==='1')return;form.setAttribute('data-gwa-note-bound','1');var recordEl=document.getElementById('gwa-note-record');var kindEl=document.getElementById('gwa-note-kind');var bodyEl=document.getElementById('gwa-note-body');var dateEl=document.getElementById('gwa-note-date');var submitEl=document.getElementById('gwa-note-submit');var alertEl=document.getElementById('gwa-note-alert');var statusEl=document.getElementById('gwa-note-status');var emptyEl=document.getElementById('gwa-note-empty');if(!recordEl||!kindEl||!bodyEl||!dateEl||!submitEl||!alertEl||!statusEl||!emptyEl)return;var snapshot=window.gwaDirectedSnapshot||null;var busy=false;var selectedId='';var pendingEventId='';var pendingFingerprint='';function textOr(value){return value==null?'':String(value).trim();}function formatDate(value){var d=new Date(value);if(isNaN(d.getTime()))return 'Fecha desconocida';try{return d.toLocaleString();}catch(e){return String(value||'Fecha desconocida');}}function contactLabel(record){var d=(record&&record.destination)||{};return textOr(d.contact_name)||textOr(d.company_name)||textOr(d.email)||'Contacto';}function recordLabel(record){return formatDate(record&&record.occurred_at)+' · '+contactLabel(record);}function emailRecords(){var thread=snapshot&&snapshot.thread;if(!thread||!Array.isArray(thread.records))return [];return thread.records.filter(function(record){return record&&record.id!=null&&record.campaign_id!=null&&!record.superseded_by;});}function selectedRecord(){var id=recordEl.value;if(!id)return null;var records=emailRecords();for(var i=0;i<records.length;i+=1){if(String(records[i].id)===id)return records[i];}return null;}function isBusy(){return Boolean(busy||window.gwaDirectedActionBusy||(snapshot&&snapshot.busy));}function hasFields(){var record=selectedRecord();var dateValue=dateEl.value;if(!record||!bodyEl.value.trim()||!dateValue)return false;var d=new Date(dateValue);return !isNaN(d.getTime());}function showAlert(message){alertEl.textContent=message;alertEl.hidden=false;}function clearAlert(){alertEl.textContent='';alertEl.hidden=true;}function showStatus(message){statusEl.textContent=message;statusEl.hidden=false;}function clearStatus(){statusEl.textContent='';statusEl.hidden=true;}function update(){var records=emailRecords();var previous=selectedId||recordEl.value||'';recordEl.textContent='';var found=false;records.forEach(function(record){var option=document.createElement('option');option.value=String(record.id);option.textContent=recordLabel(record);if(option.value===previous){option.selected=true;found=true;}recordEl.appendChild(option);});if(found){selectedId=previous;recordEl.value=previous;}else{selectedId='';recordEl.selectedIndex=-1;}var noRecords=records.length===0;emptyEl.hidden=!noRecords;var locked=isBusy()||noRecords;recordEl.disabled=locked;kindEl.disabled=locked;bodyEl.disabled=locked;dateEl.disabled=locked;submitEl.disabled=locked||!hasFields();}recordEl.addEventListener('change',function(){selectedId=recordEl.value;update();});kindEl.addEventListener('change',update);bodyEl.addEventListener('input',update);dateEl.addEventListener('input',update);dateEl.addEventListener('change',update);document.addEventListener('gwa:directed',function(event){var detail=event&&event.detail;snapshot=detail&&detail.snapshot?detail.snapshot:(detail||window.gwaDirectedSnapshot||null);update();});form.addEventListener('submit',async function(event){event.preventDefault();if(isBusy()||submitEl.disabled)return;var record=selectedRecord();var kind=kindEl.value;var body=bodyEl.value;var dateValue=dateEl.value;if(!record||!record.campaign_id||(kind!=='note'&&kind!=='response')||!body.trim()||!dateValue)return;var occurred=new Date(dateValue);if(isNaN(occurred.getTime())){showAlert('La fecha de interacción no es válida.');update();return;}var payload={kind:kind,body:body,occurred_at:occurred.toISOString(),event_id:'',distribution_id:record.id};var fingerprint=String(record.campaign_id)+'|'+String(record.id)+'|'+kind+'|'+body+'|'+payload.occurred_at;if(fingerprint!==pendingFingerprint||!pendingEventId){pendingFingerprint=fingerprint;pendingEventId=crypto.randomUUID();}payload.event_id=pendingEventId;var endpoint='/api/campaigns/'+encodeURIComponent(record.campaign_id)+'/interactions';clearAlert();clearStatus();window.gwaDirectedActionBusy=true;busy=true;var posted=false;try{update();await window.gwaApi(endpoint,'POST',payload);posted=true;window.gwaDirectedActionBusy=false;pendingEventId='';pendingFingerprint='';showStatus('Interacción guardada.');await window.gwaReloadDirected();bodyEl.value='';dateEl.value='';}catch(error){if(!posted){window.gwaDirectedActionBusy=false;showAlert('No se pudo guardar la interacción. Inténtalo de nuevo.');}}finally{busy=false;update();}});update();})();</script></form>'''